  ('deep-squat-hold', 'Deep squat hold', array['malasana', 'squat hold', 'resting squat'], 'mobility'::public.exercise_category, 'bodyweight'::public.equipment, 'compound'::public.exercise_mechanic, 'duration'::public.exercise_log_type, false, array['Squat as deep as you can with heels on the floor.', 'Use your elbows to press your knees out and keep your chest up.', 'Hold and breathe.'], '{}'::text[], '{}'::text[], 2.3, false, null),
  ('open-book-rotation', 'Open book rotation', array['thoracic rotation', 'open book', 't-spine rotation'], 'mobility'::public.exercise_category, 'bodyweight'::public.equipment, 'isolation'::public.exercise_mechanic, 'bodyweight_reps'::public.exercise_log_type, false, array['Lie on your side with knees bent and arms stretched out together in front.', 'Open the top arm over to the other side, following it with your eyes.', 'Return and repeat, then switch sides.'], '{}'::text[], '{}'::text[], 2.3, false, null),
  ('doorway-chest-stretch', 'Doorway chest stretch', array['chest stretch', 'pec stretch'], 'mobility'::public.exercise_category, 'bodyweight'::public.equipment, 'isolation'::public.exercise_mechanic, 'duration'::public.exercise_log_type, false, array['Place your forearm on a doorframe with your elbow at shoulder height.', 'Step through the door until you feel a stretch across your chest.', 'Hold, then switch sides.'], '{}'::text[], '{}'::text[], 2.3, false, null),
  ('band-shoulder-dislocate', 'Band shoulder dislocate', array['shoulder dislocates', 'pass through', 'band pass through'], 'mobility'::public.exercise_category, 'band'::public.equipment, 'isolation'::public.exercise_mechanic, 'bodyweight_reps'::public.exercise_log_type, false, array['Hold a band or stick wide in front of your thighs.', 'With straight arms, lift it over your head and behind you.', 'Bring it back over to the front. Narrow your grip over time.'], '{}'::text[], '{}'::text[], 2.3, false, null),
  ('overhead-lat-stretch', 'Overhead lat stretch', array['lat stretch'], 'mobility'::public.exercise_category, 'bodyweight'::public.equipment, 'isolation'::public.exercise_mechanic, 'duration'::public.exercise_log_type, false, array['Hold a rack or doorframe at head height with one or both hands.', 'Sit your hips back and let your chest sink until you feel the stretch along your sides.', 'Hold and breathe.'], '{}'::text[], '{}'::text[], 2.3, false, null)
) as v (
  slug, name, aliases, category, equipment, mechanic, log_type, unilateral,
  instructions, tips, common_mistakes, met_value, is_rankable, rank_key
)
on conflict (slug) where created_by is null do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  equipment = excluded.equipment,
  mechanic = excluded.mechanic,
  log_type = excluded.log_type,
  unilateral = excluded.unilateral,
  instructions = excluded.instructions,
  tips = excluded.tips,
  common_mistakes = excluded.common_mistakes,
  met_value = excluded.met_value,
  is_rankable = excluded.is_rankable,
  rank_key = excluded.rank_key;

delete from public.exercise_muscles em
using public.exercises e
where em.exercise_id = e.id and e.created_by is null;

