begin
  if (select count(*) from public.exercise_muscles em
      join public.exercises e on e.id = em.exercise_id
      where e.created_by is null) <> 814 then
    raise exception 'Exercise library v1: muscle links did not all insert.';
  end if;
end;
$$;

update public.exercise_library_meta set version = 1, updated_at = now();
